var n={en:`One tenant runs exports that starve others of DB connections. Other customers see p99 >5 s; target is <800 ms.`,ua:`Один тенант експортує дані й займає з’єднання БД. Інші бачать p99 понад 5 с; ціль — менш ніж 800 мс.`};var a={en:[`Separate interactive traffic from batch exports.`,`Design per-tenant worker limits and fair scheduling.`,`Add tenant-safe latency and queue metrics with two-tenant load tests.`],ua:[`Відокрем інтерактивні запити від експорту.`,`Спроєктуй ліміти воркерів і справедливу чергу.`,`Додай метрики без витоку даних та тест двох тенантів.`]};var r=[{en:`One tenant cannot monopolize all worker concurrency.`,ua:`Один тенант не займає всі воркери.`},{en:`Interactive latency is observable separately from export completion.`,ua:`Затримка API вимірюється окремо від завершення експорту.`}];var s={scenario:n,tasks:a,checks:r};export{r as checks,s as default,n as scenario,a as tasks};